/* =======================================================
   🎀 Pluto's Sanrio Y2K Theme Root & Colors 🎀
   ======================================================= */

@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@600;800;900&family=Noto+Sans+SC:wght@400;500;700;900&display=swap');

:root {
  --theme-color-1: #2c2828; /* 库洛米深炭黑 */
  --theme-color-2: #f4aab9; /* 草莓软糖粉 */
  --theme-accent: #d66c81;  /* 深草莓粉 */
  --ui-color-dark: rgba(244, 235, 239, 0.96); /* 淡淡的灰粉色背景 */
  --text-color-main: #2c2828; /* 炭黑色正文 */
  --mes-width: 100%;
  --mes-max-width: 720px;
  --mes-block-width: 96%;
  --box-border-radius: 5px;
  --border-radius-small: 5px;
  --border-radius-medium: 10px;
  --spacing-long: 10px;
  --spacing-short: 5px;
  --top-distance: 0px;
  --bottom-distance: 0px;
  --chat-send-spacing: 0px;
  --scroll-width: 4px;
  --avatar-w: 110px;
  --avatar-h: 147px;
}

/* 全局字体设定 */
body { 
    font-family: 'Segoe UI', 'Noto Sans SC', 'PingFang SC', sans-serif; 
    font-weight: 400; 
    color: var(--text-color-main); 
}

/* 滚动条美化 */
::-webkit-scrollbar { 
    width: var(--scroll-width); 
}
::-webkit-scrollbar-track { 
    background: transparent; 
}
::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
    background: var(--theme-color-2); 
    border: 1px solid var(--theme-color-1); 
    border-radius: 10px; 
    box-shadow: none; 
}

/* =======================================================
   🎀 Pluto's Sanrio Y2K - User Bubble 🎀
   ======================================================= */

/* 主容器 */
.mes[is_user="true"] {
    margin-top: 170px !important; 
    margin-bottom: 30px !important;
    position: relative !important;

    /* 🎀 宽度缩小 🎀 */
    width: 90% !important; 
    max-width: 680px !important; 
    margin-left: auto !important; 
    margin-right: auto !important; 
    background-color: #ffffff !important;
    background-image: linear-gradient(rgba(244, 170, 185, 0.25) 2px, transparent 2px),
                      linear-gradient(90deg, rgba(244, 170, 185, 0.25) 2px, transparent 2px) !important;
    background-size: 24px 24px !important;
    background-position: center top !important;

    border: 3px solid #2c2828 !important;
    border-radius: 20px !important;
    padding: 20px !important;
    box-shadow: 6px 6px 0px #2c2828 !important;
}

/* =======================================
   顶部的三丽鸥名片卡
   ======================================= */
/* 背景图 */
.mes[is_user="true"]::before {
    content: "" !important;
    position: absolute !important;
    top: -150px !important; 
    left: -3px !important; 
    width: calc(100% + 6px) !important;
    height: 130px !important; 
    background-image: url('https://i.ibb.co/FLfbhZGG/IMG-8561.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    border: 3px solid #2c2828 !important;
    border-radius: 20px !important;
    box-shadow: 6px 6px 0px #2c2828 !important;
    z-index: 1 !important;
    pointer-events: none !important;
}

/* 头像区 */
.mes[is_user="true"] .avatar {
    position: absolute !important;
    top: -130px !important; 
    left: 20px !important;
    right: auto !important;
    width: 90px !important;
    height: 90px !important;
    border-radius: 50% !important;
    border: 3px solid #2c2828 !important;
    box-shadow: 4px 4px 0px #2c2828 !important;
    background: #ffffff !important;
    padding: 2px !important;
    z-index: 5 !important;
    margin: 0 !important;
}
.mes[is_user="true"] .avatar img { width: 100% !important; height: 100% !important; border-radius: 50% !important; object-fit: cover !important; box-shadow: none !important; }

/* 头像挂件 */
