                rgba(20, 70, 120, 0.75) 100%);
    border-bottom: 1.5px solid #2c6e9e;  
    text-shadow: 
        0 0 6px rgba(70, 150, 220, 0.9),
        0 0 14px rgba(30, 100, 160, 0.7);
    box-shadow: 0 4px 6px -2px rgba(0, 0, 0, 0.2);
    padding: 2px 5px;
    margin: 0 3px;
    border-radius: 4px;
    line-height: 1.6;
    cursor: default;
    transition: all 0.3s ease;
    quotes: none;
}

/* 旋转星星 */
