    content: "⭐";
    font-size: 0.65em;
    display: inline-block;
    vertical-align: baseline;
    margin-left: 1px;
    position: relative;
    top: -2px;
    animation: cinna-spin 3s linear infinite;
    transform-origin: center;
    background: none;
    box-shadow: none;
    text-shadow: none;
}

@keyframes cinna-spin {
    from { transform: rotate(0deg); }
    to   { transform: rotate(360deg); }
}

