/* =======================================================
   🎀 Pluto's Sanrio Y2K - Part 4: Inputs & Controls (交互控件) 🎀
   ======================================================= */

/* 文本输入框 & 文本区 */
input[type="text"], input[type="number"], input[type="switch"],
input:not([type]), textarea:not([type="search"]) {
    background-color: rgba(244, 235, 239, 0.96) !important;
    border: 2px solid #2c2828 !important; /* 炭黑边框 */
    border-radius: 12px !important;
    color: #2c2828 !important;
    padding: 8px 12px !important;
    font-family: 'Nunito', 'Noto Sans SC', sans-serif !important;
    font-weight: 400 !important;
    box-shadow: 3px 3px 0 rgba(244, 170, 185, 0.5) !important; /* 柔和粉色阴影 */
    transition: all 0.2s ease !important;
}

/* 打字聚焦时 */
input[type="text"]:focus, input[type="number"]:focus, input[type="switch"]:focus,
input:not([type]):focus, textarea:not([type="search"]):focus {
    border: 2px dashed #d66c81 !important; /* 深草莓粉虚线 */
    background-color: #fffafb !important;
    outline: none !important;
}

/* 搜索栏特例 */
textarea[type="search"] { background-color: transparent !important; border: none !important; box-shadow: none !important; }
.text_pole { background-color: transparent !important; border: none !important; }

/* 下拉菜单 (Select) */
select {
    background-color: #ffffff !important; 
    color: #2c2828 !important;
    border: 2px solid #2c2828 !important;
    border-radius: 10px !important;
    padding: 4px 8px !important;
    font-family: 'Nunito', 'Noto Sans SC', sans-serif !important;
    font-weight: 800 !important;
    box-shadow: 2px 2px 0 #f4aab9 !important;
    margin: calc(var(--mainFontSize) * 0.3) 0 !important;
    cursor: pointer !important;
    transition: all 0.2s ease !important;
}
select:hover {
    transform: translate(-1px, -1px) !important;
    box-shadow: 3px 3px 0 #f4aab9 !important;
}
select option { background-color: #ffffff !important; color: #2c2828 !important; font-weight: 600 !important; }
select option:checked { background-color: #f4aab9 !important; color: #ffffff !important; font-weight: 900 !important; }
select option:not(:checked) { color: #7a6b6e !important; }

/* 复选框 (Checkbox) */
input[type="checkbox"] {
    width: calc(var(--mainFontSize) * 1.2) !important; 
    height: calc(var(--mainFontSize) * 1.2) !important;
    border: 2px solid #2c2828 !important; 
    border-radius: 6px !important; /* 微微圆角的正方形 */
    outline: none !important; 
    background-color: #ffffff !important; 
    box-shadow: 2px 2px 0 #f4aab9 !important;
    margin: 3px 6px 3px 0 !important;
    cursor: pointer !important;
    appearance: none !important; /* 洗掉默认又丑又旧的勾选框 */
    position: relative !important;
    transition: all 0.2s ease !important;
}
input[type="checkbox"]:hover { 
    transform: translate(-1px, -1px) !important; 
    box-shadow: 3px 3px 0 #f4aab9 !important; 
}
/* 打勾时的状态 */
input[type="checkbox"]:checked {
    background-color: #f4aab9 !important;
}
input[type="checkbox"]:checked::after {
    content: "🌸" !important;
    position: absolute !important;
    top: 50% !important; left: 50% !important;
    transform: translate(-50%, -50%) !important;
    font-size: 0.8em !important;
    font-weight: 900 !important;
}
/* 移除内部阴影 */
input[type="checkbox"]::before { box-shadow: none !important; display: none !important; }

/* 滑动条 (Range Sliders) */
input[type="range"] { 
    background-color: #f4ebef !important; 
    border: 2px solid #2c2828 !important;
    border-radius: 10px !important;
    height: 12px !important;
}
/* 滑块本体 */
input[type="range"]::-webkit-slider-thumb {
    background: #f4aab9 !important; /* 草莓粉圆球 */
    width: 18px !important; 
    height: 18px !important; 
    border: 2px solid #2c2828 !important; 
    border-radius: 50% !important;
    box-shadow: 2px 2px 0 #2c2828 !important; 
    cursor: pointer !important;
    transition: transform 0.1s !important;
}
input[type="range"]::-webkit-slider-thumb:hover {
    transform: scale(1.2) !important; 
}

/* 各种面板里的实体按钮 (Menu Buttons) */
.menu_button:not(.mes_edit_buttons *) {
    background-color: #ffffff !important;
    border: 2px solid #2c2828 !important;
    border-radius: 12px !important;
    font-weight: 800 !important;
    padding: 6px 12px !important;
    box-shadow: 3px 3px 0 #f4aab9 !important;
    transition: all 0.2s ease !important;
    cursor: pointer !important;
}
/* 按钮悬停 */
.menu_button:not(.mes_edit_buttons *):hover {
    background-color: #fffafb !important;
    border-color: #2c2828 !important; 
    box-shadow: 4px 4px 0 #2c2828 !important;     transform: translate(-1px, -1px) !important;
}
/* 按钮按下 */
.menu_button:not(.mes_edit_buttons *):active {
    transform: translate(2px, 2px) !important;
    box-shadow: 1px 1px 0 #2c2828 !important;
}

/* 还原图标本色 */
.mes_button, .mes_edit_buttons { filter: none !important; }
